var q=String(s||"").replace(/^\s+|\s+$/g,"");
if(!q)return[];
var p=Math.max(1,Number(page||1));
var base=String(basicUrl||"https://se.btlm.one").replace(/\/+$/,"");
var url=base+"/search/"+encodeURIComponent(q);
if(p>1)url+="?p="+p;
var ua="Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/128.0 Safari/537.36";

function clean(v){
    return String(v||"").replace(/\s+/g," " ).replace(/^\s+|\s+$/g,"");
}
function toBytes(v){
    var m=String(v||"").match(/([0-9.]+)\s*(TB|GB|MB|KB|B)/i);
    if(!m)return 0;
    var n=Number(m[1]||0),u=String(m[2]||"B").toUpperCase(),pow=0;
    if(u==="KB")pow=1;else if(u==="MB")pow=2;else if(u==="GB")pow=3;else if(u==="TB")pow=4;
    return Math.round(n*Math.pow(1024,pow));
}
function hashOf(v){
    var m=String(v||"").match(/btih:([A-Fa-f0-9]{40}|[A-Za-z2-7]{32})/i);
    if(!m)m=String(v||"").match(/(?:^|\/)([A-Fa-f0-9]{40})(?:$|[?#\/])/);
    if(!m)m=String(v||"").match(/([A-Fa-f0-9]{40})/);
    return m?String(m[1]).toUpperCase():"";
}
function magnet(h,t){
    var u="magnet:?xt=urn:btih:"+h;
    if(t)u+="&dn="+encodeURIComponent(t);
    return u;
}

var html=String(request(url,{headers:{"User-Agent":ua,"Accept":"text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8","Accept-Language":"zh-CN,zh;q=0.9,en;q=0.6","Referer":base+"/"},timeout:6500})||"");
if(!html)throw new Error("BT联盟搜索页空响应："+url);
if(/captcha|cloudflare|access denied|forbidden|recaptcha|challenge/i.test(html))throw new Error("BT联盟触发网页验证");

var arr=[];
var sels=["body&&li.media","body&&.media-list&&li.media","body&&.media"];
for(var si=0;si<sels.length;si++){
    try{arr=parseDomForArray(html,sels[si])||[];}catch(e0){arr=[];}
    if(arr.length)break;
}
var out=[],seen={};
for(var i=0;i<arr.length;i++){
    var block=arr[i];
    var title="";
    try{title=clean(parseDomForHtml(block,"h4&&a.title&&Text"));}catch(e1){}
    if(!title){try{title=clean(parseDomForHtml(block,"h4&&a&&Text"));}catch(e2){}}
    if(!title)continue;

    var detail="";
    try{detail=parseDomForHtml(block,"h4&&a&&href");}catch(e3){}
    detail=String(detail||"").replace(/&amp;/g,"&");
    if(detail&&detail.indexOf("http")!==0){
        if(detail.charAt(0)!=="/")detail="/"+detail;
        detail=base+detail;
    }

    var raw=String(block||"");
    var mm=raw.match(/href\s*=\s*["'](magnet:\?xt=urn:btih:[^"']+)["']/i);
    var mag=mm?String(mm[1]).replace(/&amp;/g,"&"):"";
    var h=hashOf(mag)||hashOf(detail)||hashOf(raw);
    if(!mag&&h)mag=magnet(h,title);

    var tx="";
    try{tx=clean(parseDomForHtml(block,"Text"));}catch(e4){tx=clean(raw.replace(/<[^>]+>/g," "));}
    var sm=tx.match(/文件大小\s*[:：]?\s*([0-9.]+\s*(?:TB|GB|MB|KB|B))/i);
    var fm=tx.match(/文件数量\s*[:：]?\s*(\d+)/i);
    var dm=tx.match(/(?:收录时间|收录日期)\s*[:：]?\s*([0-9]{2,4}[-\/.][0-9]{1,2}[-\/.][0-9]{1,2})/i);
    var hm=tx.match(/(?:热度|种子热度|下载次数)\s*[:：]?\s*(\d+)/i);
    var desc=[];
    if(sm)desc.push(sm[1]);
    if(fm)desc.push(fm[1]+"个文件");
    if(hm)desc.push("热度"+hm[1]);

    var key=h||mag||detail||title;
    if(seen[key])continue;
    seen[key]=1;
    var item={title:title,bytes:sm?toBytes(sm[1]):0,seeders:hm?Number(hm[1]):-1,peers:-1,date:dm?dm[1]:"",desc:desc.join(" · ")};
    if(mag)item.magnet=mag;
    else if(detail)item.url=detail;
    if(item.magnet||item.url)out.push(item);
}
if(out.length)return out;

var plain=clean(html.replace(/<script[\s\S]*?<\/script>/gi," " ).replace(/<style[\s\S]*?<\/style>/gi," " ).replace(/<[^>]+>/g," "));
var cm=plain.match(/搜索结果\s*([0-9,]+)\s*条/);
if(cm&&Number(String(cm[1]).replace(/,/g,""))===0)return[];
if(cm)throw new Error("BT联盟已命中真实 /search/ 路由（"+cm[1]+"条），但 .media 列表未解析");
throw new Error("BT联盟真实 /search/ 路由已请求，但未识别 SCDht 结果结构："+url);

